<?php declare(strict_types=1); $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Restricted safeguarding case</title><main><h1><?= $e($case['case_reference']) ?></h1><p>Assigned specialist access only. Viewing and actions are audited.</p><h2><?= $e($case['category']) ?> · <?= $e($case['severity']) ?> · <?= $e($case['status']) ?></h2><h3>Summary</h3><p><?= $e($case['summary']??'Content erased under approved retention policy.') ?></p><h3>Details</h3><p><?= nl2br($e($case['details']??'Content erased under approved retention policy.')) ?></p><?php if($case['subject_reference']!==null):?><p>Related reference: <?= $e($case['subject_reference']) ?></p><?php endif;?><?php if(!$case['content_destroyed'] && $case['status']!=='closed'):?><form method="post" action="/admin/safeguarding/cases/<?= $e($case['id']) ?>/transition"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Next status<select name="status" required><?php foreach(['triaged','investigating','action_required','resolved','closed'] as $s):?><option value="<?= $e($s) ?>"><?= $e($s) ?></option><?php endforeach;?></select></label><label>Reason<textarea name="reason" minlength="10" maxlength="1000" required></textarea></label><button>Record transition</button></form><?php endif;?><h2>Event history</h2><?php foreach($case['events'] as $event):?><p><strong><?= $e($event['event_key']) ?></strong> <?= $e($event['created_at']) ?> — <?= $e($event['note']??'') ?></p><?php endforeach;?><a href="/admin/safeguarding/cases">Back to assigned cases</a></main>